    reg [D_INDEX_BITS-1:0] writeback_index;
    reg writeback_is_sweep;
    // sweep_index 属于cache 维护扫描，保存表或队列的索引，须配合有效位与对应所有者使用。
    // 扫描须覆盖相应组和路，并等待必要的写回完成。
    reg [D_INDEX_BITS-1:0] sweep_index;
    // fence_pending 挂起的 cache 维护请求，清理扫描和必要写回结束之前不能当作维护完成。
    reg fence_pending, invalidate_data;
    // d_index 属于D-cache 控制，保存表或队列的索引，须配合有效位与对应所有者使用。
    // d_index 读取 d_address[6+D_INDEX_BITS-1:6] 所选位域；位索引按声明中的高低位顺序解释。
    wire [D_INDEX_BITS-1:0] d_index = d_address[6+D_INDEX_BITS-1:6];
    // d_match_first 的资格组合为 d_valid && d_tag == d_address[31:6+D_INDEX_BITS]。
    wire d_match_first = d_valid && d_tag == d_address[31:6+D_INDEX_BITS];
    // d_match_second 的资格组合为 D_WAYS>1 && d_second_valid && d_second_tag == d_address[31:6+D_INDEX_BITS]。
    wire d_match_second = D_WAYS>1 && d_second_valid &&
                          // d_second_tag 按 = d_address[31:6+D_INDEX_BITS] 计算，运算位宽与有无符号以原声明和显式扩展为准。
                          d_second_tag == d_address[31:6+D_INDEX_BITS];
    // d_hit 的资格组合为 d_match_first || d_match_second。
    wire d_hit = d_match_first || d_match_second;
    // selected_way 保存cache 路选择，必须和本次命中或牺牲行的 tag 同步。
    // selected_way 按 d_match_first 进行来源选择。
    // 真分支取 1'b0；其余情况取 d_match_second ? 1'b1 : !d_valid ? 1'b0 : (D_WAYS>1 && !d_second_valid) ? 1'b1 : (D_WAYS>1 && d_lru)。
    wire selected_way = d_match_first ? 1'b0 : d_match_second ? 1'b1 :
                        !d_valid ? 1'b0 : (D_WAYS>1 && !d_second_valid) ? 1'b1 :
                        (D_WAYS>1 && d_lru);
    // selected_valid 保存有效资格，标识该项是否属于当前仍可使用的事务。
    // selected_valid 按 selected_way 进行来源选择。
    // 真分支取 d_second_valid；其余情况取 d_valid。
    wire selected_valid=selected_way ? d_second_valid : d_valid;
    // selected_dirty 保存数据已被本地修改的标志，替换或维护时可能需要先写回。
    // selected_dirty 按 selected_way 进行来源选择。
    // 真分支取 d_second_dirty；其余情况取 d_dirty。
    wire selected_dirty=selected_way ? d_second_dirty : d_dirty;
    // selected_tag 保存生产者或事务标签，用于把结果匹配到正确的所有者。
    // selected_tag 按 selected_way 进行来源选择。
    // 真分支取 d_second_tag；其余情况取 d_tag。
    wire [D_TAG_BITS-1:0] selected_tag=selected_way ? d_second_tag : d_tag;
    // selected_segment 按 selected_way 进行来源选择。
    // 真分支取 d_second_segment；其余情况取 d_segment。
    wire [63:0] selected_segment=selected_way ? d_second_segment : d_segment;
    // sweep_is_last 的资格组合为 (sweep_index==D_LINES-1) && (D_WAYS==1 || sweep_way)。
    wire sweep_is_last=(sweep_index==D_LINES-1) && (D_WAYS==1 || sweep_way);
    // i_complete 的资格组合为 imem_response_valid && imem_response_ready。
    wire i_complete = imem_response_valid && imem_response_ready;
    // d_complete 的资格组合为 dmem_response_valid && dmem_response_ready。
    wire d_complete = dmem_response_valid && dmem_response_ready;
    // new_i 的资格组合为 imem_request_valid && imem_request_ready。
    wire new_i = imem_request_valid && imem_request_ready;
    // A speculative RAM/tag payload read grants no request/state ownership.
    // Ready is true only at idle or an actual response transfer, so a held
    // valid response cannot be overwritten. Remove frontend late correction
    // /request_valid from the synchronous RAM read-address selection.
    // Payload reads are safe at every idle/response-transfer edge, including
    // non-executable or unaligned private addresses. Actual new_i ownership
    // still validates the full address and returns the original precise error.
    // Never overwrite a held response: ready remains false under backpressure.
    // Maintenance still blocks actual request readiness/ownership. Reading
    // private payload while idle (or consuming a real held response) cannot
    // acquire state, and avoids a late fence/recovery cone on RAM addresses.
    // i_speculative_read 的资格组合为 !reset&&(i_state==I_IDLE||i_complete)。
    wire i_speculative_read=!reset&&(i_state==I_IDLE||i_complete);
    // new_d 的资格组合为 dmem_request_valid && dmem_request_ready。
    wire new_d = dmem_request_valid && dmem_request_ready;
    // maintenance_request 的资格组合为 fence_pending || fence_i || fence_d。
    wire maintenance_request = fence_pending || fence_i || fence_d;
    // Free payload capture does not acquire a request, change state, or
    // start an IO transaction. Maintenance and held responses retain fields.
    // d_payload_free 连接到 dmem_request_ready，两者在此路径上保持字段对应。
    wire d_payload_free=dmem_request_ready;
`ifdef VERILATOR
    reg prior_d_owned;
    reg [70:0] prior_d_payload;
    always @(posedge clk)begin
        // 复位分支建立下列状态的初始值；其后的正常更新分支在复位不成立时才执行。
        if(reset)begin prior_d_owned<=0;prior_d_payload<=0;end
        else begin
            if(new_d&&!d_payload_free)$fatal(1,"R42 accepted data request without free private payload slot");
            if(prior_d_owned&&{d_address,d_write,d_wdata,d_wstrb,d_size}!=prior_d_payload)
                $fatal(1,"R42 owned cache request payload differs from original accepted request");
            if(new_d)begin prior_d_owned<=1;prior_d_payload<=
                {dmem_request_address,dmem_request_write,dmem_request_wdata,dmem_request_wstrb,dmem_request_size};end
            else if(d_complete)prior_d_owned<=0;
        end
    end
`endif
    // next_d_index 保存表或队列的索引，须配合有效位与对应所有者使用。
    // next_d_index 读取 dmem_request_address[6+D_INDEX_BITS-1:6] 所选位域；位索引按声明中的高低位顺序解释。
    wire [D_INDEX_BITS-1:0] next_d_index = dmem_request_address[6+D_INDEX_BITS-1:6];
    // d_segment_index 属于D-cache 控制，保存表或队列的索引，须配合有效位与对应所有者使用。
    // d_segment_index 读取 d_address[6+D_INDEX_BITS-1:3] 所选位域；位索引按声明中的高低位顺序解释。
    wire [D_INDEX_BITS+2:0] d_segment_index=d_address[6+D_INDEX_BITS-1:3];
    // next_d_segment 读取 dmem_request_address[6+D_INDEX_BITS-1:3] 所选位域；位索引按声明中的高低位顺序解释。
    wire [D_INDEX_BITS+2:0] next_d_segment=dmem_request_address[6+D_INDEX_BITS-1:3];
    // new_i_pair 读取 imem_request_address[6+I_INDEX_BITS-1:3] 所选位域；位索引按声明中的高低位顺序解释。
    wire [I_INDEX_BITS+2:0] new_i_pair=imem_request_address[6+I_INDEX_BITS-1:3];
    // new_i_even_pair 按 new_i_pair+{{(I_INDEX_BITS+2){1'b0}},imem_request_address[2]} 计算，运算位宽与有无符号以原声明和显式扩展为准。
    wire [I_INDEX_BITS+2:0] new_i_even_pair=new_i_pair+{{(I_INDEX_BITS+2){1'b0}},imem_request_address[2]};
    // cross_i_pair 读取 i_next_address[6+I_INDEX_BITS-1:3] 所选位域；位索引按声明中的高低位顺序解释。
    wire [I_INDEX_BITS+2:0] cross_i_pair=i_next_address[6+I_INDEX_BITS-1:3];
    // next_write_beat 保存当前行传输拍号，用于组合完整 cache 行及标记末拍。
    // next_write_beat 按 d_beat+3'd1 计算，运算位宽与有无符号以原声明和显式扩展为准。
    wire [2:0] next_write_beat=d_beat+3'd1;
    // store_byte_enable 保存功能或输出使能，控制资格而非实际吞吐测量值。
    // store_byte_enable 按 d_address[2] 进行来源选择。
    // 真分支取 {d_wstrb,4'b0}；其余情况取 {4'b0,d_wstrb}。
    wire [7:0] store_byte_enable=d_address[2] ? {d_wstrb,4'b0} : {4'b0,d_wstrb};
    // store_replicated 按从高位到低位的拼接顺序组成，保留各字段原来的位置关系。
    // 拼接源为 {d_wdata,d_wdata}；复制大括号表示重复位域，不是独立队列元素。
    wire [63:0] store_replicated={d_wdata,d_wdata};
    integer n;

    // 判断物理地址是否允许取指，范围检查与数据 MMIO 分类不能互相替代。
    function executable;
        // address 保存地址 payload，具体是虚拟或物理地址由所在接口边界决定。
        input [31:0] address;
        begin executable = LINUX_PHYSICAL_MAP ? (address>=DATA_RAM_BASE && address<=DATA_RAM_LIMIT) : (address[31:28]==4'h1 || address[31:28]==4'h8); end
    endfunction
    // 按当前物理地址图识别外设区域，为不可缓存访问选择独立通道。
    function peripheral;
        input [31:0] address;
        begin
            // peripheral 按 LINUX_PHYSICAL_MAP 进行来源选择。
            // 真分支取 !(address>=DATA_RAM_BASE && address<=DATA_RAM_LIMIT)；其余情况取 ((address >= 32'h30000000 && address < 32'h80000000) ||。
            peripheral = LINUX_PHYSICAL_MAP ? !(address>=DATA_RAM_BASE && address<=DATA_RAM_LIMIT) : ((address >= 32'h30000000 && address < 32'h80000000) ||
                          (address >= 32'h80000000 && address < 32'h84000000));
        end
    endfunction
    // 检查数据地址是否位于本平台允许的 RAM 范围。
    function data_ram_mapped;
        input [31:0] address;
        begin
            // data_ram_mapped 的资格组合为 !ENABLE_DATA_RAM_GUARD ||。
            data_ram_mapped = !ENABLE_DATA_RAM_GUARD ||
                (address >= DATA_RAM_BASE && address <= DATA_RAM_LIMIT);
        end
    endfunction
`ifdef VERILATOR
    initial if (ENABLE_DATA_RAM_GUARD &&
        (DATA_RAM_BASE > DATA_RAM_LIMIT || DATA_RAM_BASE[5:0] != 0 ||
         DATA_RAM_LIMIT[5:0] != 6'h3f))
        $fatal(1,"Data RAM guard requires a nonwrapping, whole-cache-line range");
`endif
    // 按字节 strobe 将新存储数据合并到原 cache 数据，未使能字节保持不变。
    function [63:0] merge_store;
        input [63:0] segment;
        input [63:0] value;
        input [7:0] enables;
        integer lane;
        begin
            // merge_store 连接到 segment，两者在此路径上保持字段对应。
            merge_store=segment;
            for(lane=0;lane<8;lane=lane+1)
                if(enables[lane])merge_store[lane*8 +: 8]=value[lane*8 +: 8];
        end
    endfunction
    wire [63:0] updated_data_segment=merge_store(selected_segment,store_replicated,store_byte_enable);

    // maintenance_busy 连接到 maintenance_request，两者在此路径上保持字段对应。
    assign maintenance_busy=maintenance_request;
    // event_icache_refill 的资格组合为 !reset && i_state==I_FILL && i_beat==3'd7 &&。
    assign event_icache_refill=!reset && i_state==I_FILL && i_beat==3'd7 &&
        instr_rvalid_i && !i_fill_error && !instr_err_i;
    // event_dcache_refill 的资格组合为 !reset && d_state==D_FILL && d_beat==3'd7 &&。
    assign event_dcache_refill=!reset && d_state==D_FILL && d_beat==3'd7 &&
        data_rd_rvalid_i && !d_fill_error && !data_rd_err_i && data_rd_rid_i==1'b0;
    // event_dcache_writeback 的资格组合为 !reset && data_wr_bvalid_i && !data_wr_berr_i &&。
    assign event_dcache_writeback=!reset && data_wr_bvalid_i && !data_wr_berr_i &&
        // data_wr_bid_i 的资格组合为 =1'b0 && (d_state==D_WRITE_ACK ||。
        data_wr_bid_i==1'b0 && (d_state==D_WRITE_ACK ||
        (d_state==D_WRITE_BEATS && d_beat==3'd7 && data_wr_gnt_i));
    // imem_request_ready 的资格组合为 !reset && !maintenance_request &&。
    assign imem_request_ready=!reset && !maintenance_request &&
                             (i_state==I_IDLE || i_complete);
    // dmem_request_ready 的资格组合为 !reset && !maintenance_request &&。
    assign dmem_request_ready=!reset && !maintenance_request &&
                             (d_state==D_IDLE || d_complete);
    // instr_req_o 的资格组合为 !reset && i_state==I_COMMAND。
    assign instr_req_o=!reset && i_state==I_COMMAND;
    // instr_addr_o 按从高位到低位的拼接顺序组成，保留各字段原来的位置关系。
    // 拼接源为 {i_address[31:6],6'b0}；复制大括号表示重复位域，不是独立队列元素。
    assign instr_addr_o={i_address[31:6],6'b0};
    assign instr_io_o=peripheral(i_address);
    // instr_rready_o 的资格组合为 !reset && (i_state==I_FILL || i_state==I_COMMAND)。
    assign instr_rready_o=!reset && (i_state==I_FILL || i_state==I_COMMAND);
    // data_rd_req_o 的资格组合为 !reset && d_state==D_READ_COMMAND。
    assign data_rd_req_o=!reset && d_state==D_READ_COMMAND;
    assign data_rd_id_o=1'b0;
    // data_rd_addr_o 按从高位到低位的拼接顺序组成，保留各字段原来的位置关系。
    // 拼接源为 {d_address[31:6],6'b0}；复制大括号表示重复位域，不是独立队列元素。
    assign data_rd_addr_o={d_address[31:6],6'b0};
    // data_rd_rready_o 的资格组合为 !reset && (d_state==D_FILL || d_state==D_READ_COMMAND)。
    assign data_rd_rready_o=!reset && (d_state==D_FILL || d_state==D_READ_COMMAND);
    // data_wr_req_o 的资格组合为 !reset && d_state==D_WRITE_BEATS。
    assign data_wr_req_o=!reset && d_state==D_WRITE_BEATS;
    // data_wr_last_o 由比较式 d_beat==3'd7 产生；该结果是条件判断，不是被比较的数据。
    assign data_wr_last_o=d_beat==3'd7;
    // data_wr_addr_o 连接到 writeback_address，两者在此路径上保持字段对应。
    assign data_wr_addr_o=writeback_address;
    // data_wr_data_o 按 writeback_way 进行来源选择。
    assign data_wr_data_o=writeback_way ? d_second_segment : d_segment;
    assign data_wr_id_o=1'b0;
    // periph_req_o 的资格组合为 !reset && d_state==D_IO_COMMAND。
    assign periph_req_o=!reset && d_state==D_IO_COMMAND;
    // periph_we_o 连接到 d_write，两者在此路径上保持字段对应。
    assign periph_we_o=d_write;
    // periph_addr_o 连接到 d_address，两者在此路径上保持字段对应。
    assign periph_addr_o=d_address;
    // periph_wdata_o 连接到 d_wdata，两者在此路径上保持字段对应。
    assign periph_wdata_o=d_wdata;
    // periph_be_o 按 d_write 进行来源选择。
    // 真分支取 d_wstrb；其余情况取 。
    assign periph_be_o=d_write ? d_wstrb :
                       (d_size==0 ? (4'b0001 << d_address[1:0]) :
                        // d_size 按 =1 选择候选来源；各分支结果仍属于当前组合路径。
                        // d_size 按 =1 进行来源选择。
                        // 真分支取 (4'b0011 << d_address[1:0])；其余情况取 4'b1111)。
                        d_size==1 ? (4'b0011 << d_address[1:0]) : 4'b1111);
    // periph_size_o 连接到 d_size，两者在此路径上保持字段对应。
    assign periph_size_o=d_size;

    always @* begin
        imem_response_valid=1'b0;
        // Data proposals are available in parallel with tag comparison.
        // Only response_valid grants a transaction; invalid-cycle data is
        // deliberately unspecified, avoiding hit -> data -> predict feedback.
        // imem_response_data 按 i_crossing 进行来源选择。
        // 真分支取 {i_word0,i_first_word}；其余情况取 {i_word1,i_word0}。
        imem_response_data=i_crossing?{i_word0,i_first_word}:{i_word1,i_word0};
        imem_response_error=2'b0;
        if (!reset && i_state==I_LOOKUP && i_hit &&
            (i_crossing || i_address[5:2]!=4'd15 || i_fast_cross_hit)) begin
            imem_response_valid=1'b1;
            if(i_crossing)imem_response_error={1'b0,i_first_error};
        end
        if (!reset && i_state==I_ERROR) begin
            imem_response_valid=1'b1;
            // imem_response_data 连接到 i_error_data，两者在此路径上保持字段对应。
            imem_response_data=i_error_data;
            // imem_response_error 连接到 i_error_bits，两者在此路径上保持字段对应。
            imem_response_error=i_error_bits;
        end
        dmem_response_valid=1'b0;
        // dmem_response_rdata 按 (d_address[2] 选择候选来源；各分支结果仍属于当前组合路径。
        dmem_response_rdata=(d_address[2]?selected_segment[63:32]:selected_segment[31:0]);
        dmem_response_error=1'b0;
        if (!reset && d_state==D_LOOKUP && d_hit) begin
            dmem_response_valid=1'b1;
        end
        if (!reset && d_state==D_RESPONSE) begin
            dmem_response_valid=1'b1;
            // dmem_response_rdata 连接到 d_result，两者在此路径上保持字段对应。
            dmem_response_rdata=d_result;
            // dmem_response_error 连接到 d_result_error，两者在此路径上保持字段对应。
            dmem_response_error=d_result_error;
        end
    end


    reg [31:0] i_even_ram_q, i_even_bypass;
    reg i_even_ram_select;
    reg [31:0] i_even_second_ram_q, i_odd_second_ram_q;
    // Select each bank's way at the payload-read edge, before the response
    // cycle. Independent registered tag checks still own response validity.
    // A miss uses the existing refill bypass, including cross-line requests.
    // i_even_read_way 属于I-cache 控制，保存cache 路选择，必须和本次命中或牺牲行的 tag 同步。
    reg i_even_read_way, i_odd_read_way;
    // i_even_word 按 i_even_ram_select 进行来源选择。
    // 真分支取 (i_even_read_way ? i_even_second_ram_q : i_even_ram_q)；其余情况取 i_even_bypass。
    assign i_even_word=i_even_ram_select ? (i_even_read_way ? i_even_second_ram_q : i_even_ram_q) : i_even_bypass;
    reg [31:0] i_odd_ram_q, i_odd_bypass;
    reg i_odd_ram_select;
    // i_odd_word 按 i_odd_ram_select 进行来源选择。
    // 真分支取 (i_odd_read_way ? i_odd_second_ram_q : i_odd_ram_q)；其余情况取 i_odd_bypass。
    assign i_odd_word=i_odd_ram_select ? (i_odd_read_way ? i_odd_second_ram_q : i_odd_ram_q) : i_odd_bypass;
    reg [63:0] d_first_ram_q, d_first_bypass;
    reg d_first_ram_select;
    // d_segment 按 d_first_ram_select 进行来源选择。
    // 真分支取 d_first_ram_q；其余情况取 d_first_bypass。
    assign d_segment=d_first_ram_select ? d_first_ram_q : d_first_bypass;
    reg [63:0] d_second_ram_q, d_second_bypass;
    reg d_second_ram_select;
    // d_second_segment 按 d_second_ram_select 进行来源选择。
    // 真分支取 d_second_ram_q；其余情况取 d_second_bypass。
    assign d_second_segment=d_second_ram_select ? d_second_ram_q : d_second_bypass;

    // i_ram_cross_lookup 的资格组合为 (i_state==I_LOOKUP && i_hit && !i_crossing && !i_fast_cross_hit && i_address[5:2]==4'd15 && executable(i_next_address))。
    wire i_ram_cross_lookup=(i_state==I_LOOKUP && i_hit && !i_crossing && !i_fast_cross_hit &&
        // i_address[5:2] 的资格组合为 =4'd15 && executable(i_next_address))。
        i_address[5:2]==4'd15 && executable(i_next_address));
    // i_ram_cross_error 属于I-cache 控制，保存访问或译码错误标志，不能被正常数据值掩盖。
    // i_ram_cross_error 的资格组合为 (i_state==I_FILL && instr_rvalid_i && i_beat==3'd7 && (i_fill_error || instr_err_i) && !i_crossing && i_address[5:2]==4'd15 && executable(i_next_address))。
    wire i_ram_cross_error=(i_state==I_FILL && instr_rvalid_i && i_beat==3'd7 &&
        (i_fill_error || instr_err_i) && !i_crossing && i_address[5:2]==4'd15 && executable(i_next_address));
    // i_ram_read 的资格组合为 !reset && (i_speculative_read || i_ram_cross_lookup || i_ram_cross_error)。
    wire i_ram_read=!reset && (i_speculative_read || i_ram_cross_lookup || i_ram_cross_error);
    // Private synchronous read payload is safe at idle or response transfer.
    // Keep actual new_d state/side-effect ownership independently qualified.
    // d_speculative_read 的资格组合为 !reset&&(d_state==D_IDLE||d_complete)。
    wire d_speculative_read=!reset&&(d_state==D_IDLE||d_complete);
    // d_ram_new_read 连接到 d_speculative_read，两者在此路径上保持字段对应。
    wire d_ram_new_read=d_speculative_read;
    // d_ram_writeback_read 的资格组合为 (d_state==D_WRITE_READ) || (d_state==D_WRITE_BEATS && data_wr_gnt_i && d_beat!=3'd7)。
    wire d_ram_writeback_read=(d_state==D_WRITE_READ) ||
        (d_state==D_WRITE_BEATS && data_wr_gnt_i && d_beat!=3'd7);
    // d_first_ram_read 的资格组合为 !reset && (d_ram_new_read || (d_ram_writeback_read && !writeback_way))。
    wire d_first_ram_read=!reset && (d_ram_new_read || (d_ram_writeback_read && !writeback_way));
    // d_second_ram_read 的资格组合为 !reset && ((d_ram_new_read && D_WAYS>1) || (d_ram_writeback_read && writeback_way))。
    wire d_second_ram_read=!reset && ((d_ram_new_read && D_WAYS>1) || (d_ram_writeback_read && writeback_way));
    // Way lookup consumes a cache-line address, not the word address + 4.
    // Query current/adjacent lines independently; select the next line only
    // for the last word. Keep late ownership/redirect muxes after tag reads.
    // i_offer_set 读取 imem_request_address[6+I_INDEX_BITS-1:6] 所选位域；位索引按声明中的高低位顺序解释。
    wire [I_INDEX_BITS-1:0] i_offer_set=imem_request_address[6+I_INDEX_BITS-1:6];
    // i_offer_tag 属于I-cache 控制，保存生产者或事务标签，用于把结果匹配到正确的所有者。
    // i_offer_tag 读取 imem_request_address[31:6+I_INDEX_BITS] 所选位域；位索引按声明中的高低位顺序解释。
    wire [I_TAG_BITS-1:0] i_offer_tag=imem_request_address[31:6+I_INDEX_BITS];
    // i_offer_next_set 按 i_offer_set+1'b1 计算，运算位宽与有无符号以原声明和显式扩展为准。
    wire [I_INDEX_BITS-1:0] i_offer_next_set=i_offer_set+1'b1;
    // i_offer_next_tag 属于I-cache 控制，保存生产者或事务标签，用于把结果匹配到正确的所有者。
    // i_offer_next_tag 按 i_offer_tag+(&i_offer_set) 计算，运算位宽与有无符号以原声明和显式扩展为准。
    wire [I_TAG_BITS-1:0] i_offer_next_tag=i_offer_tag+(&i_offer_set);
    // Any valid line has a different tag from the opposite way, even when
    // that opposite way is invalid. Refill maintains this invariant below.
    // Therefore the early data-way choice needs only a tag comparison;
    // registered valid bits still independently qualify the actual hit.
    // i_offer_way 属于I-cache 控制，保存cache 路选择，必须和本次命中或牺牲行的 tag 同步。
    // i_offer_way 的资格组合为 I_WAYS>1 && instruction_tags_second[i_offer_set]==i_offer_tag。
    wire i_offer_way=I_WAYS>1 &&
        instruction_tags_second[i_offer_set]==i_offer_tag;
    // i_offer_next_way 属于I-cache 控制，保存cache 路选择，必须和本次命中或牺牲行的 tag 同步。
    // i_offer_next_way 的资格组合为 I_WAYS>1 && instruction_tags_second[i_offer_next_set]==i_offer_next_tag。
    wire i_offer_next_way=I_WAYS>1 &&
        instruction_tags_second[i_offer_next_set]==i_offer_next_tag;
    // i_cross_lookup_set 读取 i_next_address[6+I_INDEX_BITS-1:6] 所选位域；位索引按声明中的高低位顺序解释。
    wire [I_INDEX_BITS-1:0] i_cross_lookup_set=i_next_address[6+I_INDEX_BITS-1:6];
    // i_cross_lookup_way 属于I-cache 控制，保存cache 路选择，必须和本次命中或牺牲行的 tag 同步。
    // i_cross_lookup_way 的资格组合为 I_WAYS>1 && instruction_tags_second[i_cross_lookup_set]==i_next_address[31:6+I_INDEX_BITS]。
    wire i_cross_lookup_way=I_WAYS>1 &&
        // instruction_tags_second[i_cross_lookup_set] 按 =i_next_address[31:6+I_INDEX_BITS] 计算，运算位宽与有无符号以原声明和显式扩展为准。
        instruction_tags_second[i_cross_lookup_set]==i_next_address[31:6+I_INDEX_BITS];
    always @(posedge clk) begin
        if(i_ram_read) begin
            // i_even_read_way 按 i_speculative_read 选择候选来源；各分支结果仍属于当前寄存边界。
            i_even_read_way<=i_speculative_read ?
                (imem_request_address[5:2]==4'd15 ? i_offer_next_way : i_offer_way) : i_cross_lookup_way;
            // i_odd_read_way 按 i_speculative_read 选择候选来源；各分支结果仍属于当前寄存边界。
            // 本时钟边界的 i_odd_read_way 按 i_speculative_read 进行来源选择。
            // 真分支取 i_offer_way；其余情况取 i_cross_lookup_way。
            i_odd_read_way<=i_speculative_read ? i_offer_way : i_cross_lookup_way;
            // 本时钟边界的 i_even_ram_q 读取 instruction_even[i_even_ram_read_index] 所选位域；位索引按声明中的高低位顺序解释。
            i_even_ram_q<=instruction_even[i_even_ram_read_index];
            // 本时钟边界的 i_odd_ram_q 读取 instruction_odd[i_odd_ram_read_index] 所选位域；位索引按声明中的高低位顺序解释。
            i_odd_ram_q<=instruction_odd[i_odd_ram_read_index];
            if(I_WAYS>1)begin
                // 本时钟边界的 i_even_second_ram_q 读取 instruction_even_second[i_even_ram_read_index] 所选位域；位索引按声明中的高低位顺序解释。
                i_even_second_ram_q<=instruction_even_second[i_even_ram_read_index];
                // 本时钟边界的 i_odd_second_ram_q 读取 instruction_odd_second[i_odd_ram_read_index] 所选位域；位索引按声明中的高低位顺序解释。
                i_odd_second_ram_q<=instruction_odd_second[i_odd_ram_read_index];
            end
        end
        if(d_first_ram_read) d_first_ram_q<={data_segments_byte7[d_ram_read_index],data_segments_byte6[d_ram_read_index],data_segments_byte5[d_ram_read_index],data_segments_byte4[d_ram_read_index],data_segments_byte3[d_ram_read_index],data_segments_byte2[d_ram_read_index],data_segments_byte1[d_ram_read_index],data_segments_byte0[d_ram_read_index]};
        if(d_second_ram_read) d_second_ram_q<={data_segments_second_byte7[d_ram_read_index],data_segments_second_byte6[d_ram_read_index],data_segments_second_byte5[d_ram_read_index],data_segments_second_byte4[d_ram_read_index],data_segments_second_byte3[d_ram_read_index],data_segments_second_byte2[d_ram_read_index],data_segments_second_byte1[d_ram_read_index],data_segments_second_byte0[d_ram_read_index]};
    end

`ifdef VERILATOR
    integer i_distinct_check;
    always @(posedge clk)if(!reset && I_WAYS>1)begin
        for(i_distinct_check=0;i_distinct_check<I_LINES;i_distinct_check=i_distinct_check+1)
            if((instruction_valid[i_distinct_check] || instruction_valid_second[i_distinct_check]) &&
                instruction_tags[i_distinct_check]==instruction_tags_second[i_distinct_check])
                $fatal(1,"Valid instruction line aliases opposite-way tag");
    end
    // Unique tags and the early way selection are correctness invariants,
    // not predictions: no extra cycle or retry is required on a way-1 hit.
    always @(posedge clk)if(!reset && i_state==I_LOOKUP)begin
        if(i_match_first && i_match_second)$fatal(1,"Duplicate instruction tags in one set");
        if(i_next_match_first && i_next_match_second)$fatal(1,"Duplicate next-line tags");
        if(i_hit && i_odd_ram_select && i_odd_read_way!=i_hit_way)$fatal(1,"Early odd way mismatch");
        if(i_hit && i_even_ram_select && i_address[5:2]!=4'd15 && i_even_read_way!=i_hit_way)$fatal(1,"Early even way mismatch");
        if(i_hit && i_fast_cross_hit && i_even_ram_select && i_even_read_way!=i_next_hit_way)$fatal(1,"Early next-line way mismatch");
    end
`endif

    // Prepare error payload independently of current hit/fault qualification.
    // I_ERROR never overwrites its held payload; only the matching original
    // transition below can make these private bits externally meaningful.
    always @(posedge clk)if(!reset)begin
        if(i_state==I_LOOKUP&&!i_crossing&&i_address[5:2]==4'd15)
            // 本时钟边界的 i_error_word 捕获 i_word0，两者在此路径上保持字段对应。
            i_error_word<=i_word0;
        else if(i_state==I_FILL&&instr_rvalid_i&&i_beat==3'd7)
            // 本时钟边界的 i_error_word 捕获 i_first_word，两者在此路径上保持字段对应。
            i_error_word<=i_first_word;
    end

    // FPGA RAM port lowering: unchanged architectural cycle boundary.
    // i_even_ram_read_index 属于I-cache 控制，保存表或队列的索引，须配合有效位与对应所有者使用。
    // i_even_ram_read_index 按 i_speculative_read 进行来源选择。
    // 真分支取 new_i_even_pair；其余情况取 cross_i_pair。
    wire [I_INDEX_BITS+2:0] i_even_ram_read_index=i_speculative_read ? new_i_even_pair : cross_i_pair;
    // i_odd_ram_read_index 属于I-cache 控制，保存表或队列的索引，须配合有效位与对应所有者使用。
    // i_odd_ram_read_index 按 i_speculative_read 进行来源选择。
    // 真分支取 new_i_pair；其余情况取 cross_i_pair。
    wire [I_INDEX_BITS+2:0] i_odd_ram_read_index=i_speculative_read ? new_i_pair : cross_i_pair;
    // i_ram_write_index 属于I-cache 控制，保存表或队列的索引，须配合有效位与对应所有者使用。
    // i_ram_write_index 按从高位到低位的拼接顺序组成，保留各字段原来的位置关系。
    // 拼接源为 {i_index,(i_state==I_COMMAND ? 3'b0 : i_beat)}；复制大括号表示重复位域，不是独立队列元素。
    wire [I_INDEX_BITS+2:0] i_ram_write_index={i_index,(i_state==I_COMMAND ? 3'b0 : i_beat)};
    // i_ram_write 的资格组合为 !reset && instr_rvalid_i && ((i_state==I_COMMAND && instr_gnt_i) || i_state==I_FILL)。
    wire i_ram_write=!reset && instr_rvalid_i &&
        ((i_state==I_COMMAND && instr_gnt_i) || i_state==I_FILL);
    // d_ram_read_index 属于D-cache 控制，保存表或队列的索引，须配合有效位与对应所有者使用。
    // d_ram_read_index 按 d_speculative_read 进行来源选择。
    // 真分支取 next_d_segment；其余情况取 {writeback_index,(d_state==D_WRITE_BEATS ? next_write_beat : d_beat)}。
    wire [D_INDEX_BITS+2:0] d_ram_read_index=d_speculative_read ? next_d_segment :
        {writeback_index,(d_state==D_WRITE_BEATS ? next_write_beat : d_beat)};
    // d_ram_store 属于D-cache 控制，保存存储类别资格；最终写副作用仍受顺序及握手限定。
    // d_ram_store 的资格组合为 (d_state==D_LOOKUP && d_hit && d_complete && d_write)。
    wire d_ram_store=(d_state==D_LOOKUP && d_hit && d_complete && d_write);
    // d_ram_fill 的资格组合为 data_rd_rvalid_i && ((d_state==D_READ_COMMAND && data_rd_gnt_i) || d_state==D_FILL)。
    wire d_ram_fill=data_rd_rvalid_i &&
        ((d_state==D_READ_COMMAND && data_rd_gnt_i) || d_state==D_FILL);
    // d_ram_write 的资格组合为 !reset && (d_ram_store || d_ram_fill)。
    wire d_ram_write=!reset && (d_ram_store || d_ram_fill);
    // d_ram_write_way 属于D-cache 控制，保存cache 路选择，必须和本次命中或牺牲行的 tag 同步。
    // d_ram_write_way 按 d_ram_store 进行来源选择。
    // 真分支取 selected_way；其余情况取 request_way。
    wire d_ram_write_way=d_ram_store ? selected_way : request_way;
    // d_ram_write_index 属于D-cache 控制，保存表或队列的索引，须配合有效位与对应所有者使用。
    // d_ram_write_index 按 d_ram_store 进行来源选择。
    // 真分支取 d_segment_index；其余情况取 {d_index,(d_state==D_READ_COMMAND ? 3'b0 : d_beat)}。
    wire [D_INDEX_BITS+2:0] d_ram_write_index=d_ram_store ? d_segment_index :
        {d_index,(d_state==D_READ_COMMAND ? 3'b0 : d_beat)};
    // d_ram_write_data 按 d_ram_store 进行来源选择。
    // 真分支取 store_replicated；其余情况取 data_rd_rdata_i。
    wire [63:0] d_ram_write_data=d_ram_store ? store_replicated : data_rd_rdata_i;
    // d_ram_write_mask 按 d_ram_store 进行来源选择。
    // 真分支取 store_byte_enable；其余情况取 8'hff。
    wire [7:0] d_ram_write_mask=d_ram_store ? store_byte_enable : 8'hff;
    always @(posedge clk) begin
        if(i_ram_write) begin
            if(I_WAYS>1 && i_refill_way)begin
                // 本时钟边界的 instruction_even_second[i_ram_write_index] 读取 instr_rdata_i[31:0] 所选位域；位索引按声明中的高低位顺序解释。
                instruction_even_second[i_ram_write_index]<=instr_rdata_i[31:0];
                // 本时钟边界的 instruction_odd_second[i_ram_write_index] 读取 instr_rdata_i[63:32] 所选位域；位索引按声明中的高低位顺序解释。
                instruction_odd_second[i_ram_write_index]<=instr_rdata_i[63:32];
            end else begin
                // 本时钟边界的 instruction_even[i_ram_write_index] 读取 instr_rdata_i[31:0] 所选位域；位索引按声明中的高低位顺序解释。
                instruction_even[i_ram_write_index]<=instr_rdata_i[31:0];
                // 本时钟边界的 instruction_odd[i_ram_write_index] 读取 instr_rdata_i[63:32] 所选位域；位索引按声明中的高低位顺序解释。
                instruction_odd[i_ram_write_index]<=instr_rdata_i[63:32];
            end
        end
        if(d_ram_write && d_ram_write_mask[0]) begin
            if(d_ram_write_way) data_segments_second_byte0[d_ram_write_index]<=d_ram_write_data[7:0];
            else data_segments_byte0[d_ram_write_index]<=d_ram_write_data[7:0];
        end
        if(d_ram_write && d_ram_write_mask[1]) begin
            if(d_ram_write_way) data_segments_second_byte1[d_ram_write_index]<=d_ram_write_data[15:8];
            else data_segments_byte1[d_ram_write_index]<=d_ram_write_data[15:8];
        end
        if(d_ram_write && d_ram_write_mask[2]) begin
            if(d_ram_write_way) data_segments_second_byte2[d_ram_write_index]<=d_ram_write_data[23:16];
            else data_segments_byte2[d_ram_write_index]<=d_ram_write_data[23:16];
        end
        if(d_ram_write && d_ram_write_mask[3]) begin
            if(d_ram_write_way) data_segments_second_byte3[d_ram_write_index]<=d_ram_write_data[31:24];
            else data_segments_byte3[d_ram_write_index]<=d_ram_write_data[31:24];
        end
        if(d_ram_write && d_ram_write_mask[4]) begin
            if(d_ram_write_way) data_segments_second_byte4[d_ram_write_index]<=d_ram_write_data[39:32];
            else data_segments_byte4[d_ram_write_index]<=d_ram_write_data[39:32];
        end
        if(d_ram_write && d_ram_write_mask[5]) begin
            if(d_ram_write_way) data_segments_second_byte5[d_ram_write_index]<=d_ram_write_data[47:40];
            else data_segments_byte5[d_ram_write_index]<=d_ram_write_data[47:40];
        end
        if(d_ram_write && d_ram_write_mask[6]) begin
            if(d_ram_write_way) data_segments_second_byte6[d_ram_write_index]<=d_ram_write_data[55:48];
            else data_segments_byte6[d_ram_write_index]<=d_ram_write_data[55:48];
        end
        if(d_ram_write && d_ram_write_mask[7]) begin
            if(d_ram_write_way) data_segments_second_byte7[d_ram_write_index]<=d_ram_write_data[63:56];
            else data_segments_byte7[d_ram_write_index]<=d_ram_write_data[63:56];
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            // 本时钟边界的 i_state 捕获 I_IDLE，两者在此路径上保持字段对应。
            i_state<=I_IDLE; i_address<=0; begin i_even_bypass<=0; i_even_ram_select<=1'b0; end begin i_odd_bypass<=0; i_odd_ram_select<=1'b0; end i_tag<=0; i_valid<=0;
            i_crossing<=0; i_first_word<=0; i_first_error<=0;
            i_next_tag<=0; i_next_valid<=0;
            i_second_tag<=0;i_second_valid<=0;i_next_second_tag<=0;i_next_second_valid<=0;
            i_lru<=0;i_refill_way<=0;
            i_beat<=0; i_fill_error<=0; begin i_error_data_snapshot<=0;i_error_word_valid<=0;end i_error_bits<=0;
            // d_state 在此时钟更新路径捕获 D_IDLE，该更新仍受外层条件与后续同块赋值优先级限定。
            // 本时钟边界的 d_state 捕获 D_IDLE，两者在此路径上保持字段对应。
            d_state<=D_IDLE; d_address<=0; d_write<=0; d_wdata<=0;
            d_wstrb<=0; d_size<=0; begin d_first_bypass<=0; d_first_ram_select<=1'b0; end d_tag<=0; d_valid<=0;
            begin d_second_bypass<=0; d_second_ram_select<=1'b0; end d_second_tag<=0; d_second_valid<=0; d_second_dirty<=0; d_lru<=0;
            request_way<=0; writeback_way<=0; sweep_way<=0;
            d_dirty<=0; d_beat<=0; d_fill_error<=0; d_result<=0;
            d_result_error<=0; writeback_address<=0;
            writeback_index<=0; writeback_is_sweep<=0; sweep_index<=0;
            fence_pending<=0; invalidate_data<=0;
            for (n=0;n<I_LINES;n=n+1)begin
                instruction_valid[n]<=1'b0;instruction_valid_second[n]<=1'b0;instruction_lru[n]<=0;
            end
            for (n=0;n<D_LINES;n=n+1) begin
                data_valid[n]<=1'b0;
                data_dirty[n]<=1'b0;
                data_valid_second[n]<=1'b0;
                data_dirty_second[n]<=1'b0;
                data_lru[n]<=1'b0;
            end
        end else begin
            if (fence_i || fence_d) fence_pending<=1'b1;
            if (fence_d) invalidate_data<=1'b1;
            case (i_state)
                I_LOOKUP: begin
                    if (!i_hit) begin
                        i_beat<=0; i_fill_error<=0; i_state<=I_COMMAND;
                        // i_refill_way 在此时钟更新路径捕获 i_victim_way，该更新仍受外层条件与后续同块赋值优先级限定。
                        // 本时钟边界的 i_refill_way 捕获 i_victim_way，两者在此路径上保持字段对应。
                        i_refill_way<=i_victim_way;
                        if(i_victim_way)instruction_valid_second[i_index]<=0;
                        else instruction_valid[i_index]<=0;
                    end else if (!i_crossing && i_address[5:2]==4'd15 && !i_fast_cross_hit) begin
                        // 本时钟边界的 i_first_word 捕获 i_word0，两者在此路径上保持字段对应。
                        i_first_word<=i_word0;
                        i_first_error<=0;
                        i_crossing<=1;
                        // i_address 在此时钟更新路径捕获 i_next_address，该更新仍受外层条件与后续同块赋值优先级限定。
                        // 本时钟边界的 i_address 捕获 i_next_address，两者在此路径上保持字段对应。
                        i_address<=i_next_address;
                        if (!executable(i_next_address)) begin
                            begin i_error_data_snapshot<={32'b0,i_word0};i_error_word_valid<=1;end
                            i_error_bits<=2'b10; i_state<=I_ERROR;
                        end else begin
                            i_even_ram_select<=1'b1;
                            i_odd_ram_select<=1'b1;
                            // i_tag 在此时钟更新路径捕获 instruction_tags[i_next_index]，该更新仍受外层条件与后续同块赋值优先级限定。
                            // 本时钟边界的 i_tag 读取 instruction_tags[i_next_index] 所选位域；位索引按声明中的高低位顺序解释。
                            i_tag<=instruction_tags[i_next_index];
                            // i_valid 在此时钟更新路径捕获 instruction_valid[i_next_index]，该更新仍受外层条件与后续同块赋值优先级限定。
                            // 本时钟边界的 i_valid 读取 instruction_valid[i_next_index] 所选位域；位索引按声明中的高低位顺序解释。
                            i_valid<=instruction_valid[i_next_index];
                            // i_second_tag 在此时钟更新路径捕获 instruction_tags_second[i_next_index]，该更新仍受外层条件与后续同块赋值优先级限定。
                            // 本时钟边界的 i_second_tag 读取 instruction_tags_second[i_next_index] 所选位域；位索引按声明中的高低位顺序解释。
                            i_second_tag<=instruction_tags_second[i_next_index];
                            // i_second_valid 在此时钟更新路径捕获 I_WAYS>1 && instruction_valid_second[i_next_index]，该更新仍受外层条件与后续同块赋值优先级限定。
                            // 本时钟边界的 i_second_valid 的资格组合为 I_WAYS>1 && instruction_valid_second[i_next_index]。
                            i_second_valid<=I_WAYS>1 && instruction_valid_second[i_next_index];
                            // i_lru 在此时钟更新路径捕获 instruction_lru[i_next_index]，该更新仍受外层条件与后续同块赋值优先级限定。
                            // 本时钟边界的 i_lru 读取 instruction_lru[i_next_index] 所选位域；位索引按声明中的高低位顺序解释。
                            i_lru<=instruction_lru[i_next_index];
                        end
                    end else if (i_complete) i_state<=I_IDLE;
                end
                I_COMMAND: if (instr_gnt_i) begin
                    i_state<=I_FILL;
                    i_beat<=0; i_fill_error<=0;
                    if (instr_rvalid_i) begin
                        // RAM write is in the common bank-port process below.
                        // RAM write is in the common bank-port process below.
                        if(i_address[5:3]==0)begin
                            begin i_odd_bypass<=instr_rdata_i[63:32]; i_odd_ram_select<=1'b0; end
                            if(!i_address[2])begin i_even_bypass<=instr_rdata_i[31:0]; i_even_ram_select<=1'b0; end
                        end
                        i_beat<=1; i_fill_error<=instr_err_i;
                    end
                end
                I_FILL: if (instr_rvalid_i) begin
                    // RAM write is in the common bank-port process below.
                    // RAM write is in the common bank-port process below.
                    if(i_beat==i_address[5:3])begin
                        begin i_odd_bypass<=instr_rdata_i[63:32]; i_odd_ram_select<=1'b0; end
                        if(!i_address[2])begin i_even_bypass<=instr_rdata_i[31:0]; i_even_ram_select<=1'b0; end
                    end
                    if(i_address[2] && i_address[5:3]!=3'd7 && i_beat==(i_address[5:3]+3'd1))
                        begin i_even_bypass<=instr_rdata_i[31:0]; i_even_ram_select<=1'b0; end
                    i_fill_error<=i_fill_error || instr_err_i;
                    if (i_beat==3'd7) begin
                        if (i_fill_error || instr_err_i) begin
                            if (!i_crossing && i_address[5:2]==4'd15 && executable(i_next_address)) begin
                                i_first_word<=0; i_first_error<=1; i_crossing<=1;
                                i_address<=i_next_address;
                                i_even_ram_select<=1'b1;
                                i_odd_ram_select<=1'b1;
                                i_tag<=instruction_tags[i_next_index];
                                i_valid<=instruction_valid[i_next_index];
                                i_second_tag<=instruction_tags_second[i_next_index];
                                i_second_valid<=I_WAYS>1 && instruction_valid_second[i_next_index];
                                i_lru<=instruction_lru[i_next_index];
                                i_state<=I_LOOKUP;
                            end else begin
                                begin i_error_data_snapshot<=i_crossing ? {32'b0,i_first_word} : 64'b0;i_error_word_valid<=i_crossing;end
                                i_error_bits<=i_crossing ? {1'b1,i_first_error} : 2'b11;
                                i_state<=I_ERROR;
                            end
                        end else begin
                            if(I_WAYS>1 && i_refill_way)begin
                                instruction_tags_second[i_index]<=i_address[31:6+I_INDEX_BITS];
                                instruction_valid_second[i_index]<=1'b1;
                                i_second_tag<=i_address[31:6+I_INDEX_BITS];i_second_valid<=1;
                                if(!instruction_valid[i_index])begin
                                    instruction_tags[i_index]<=~i_address[31:6+I_INDEX_BITS];
                                    i_tag<=~i_address[31:6+I_INDEX_BITS];
                                end
                            end else begin
                                instruction_tags[i_index]<=i_address[31:6+I_INDEX_BITS];
                                instruction_valid[i_index]<=1'b1;
                                i_tag<=i_address[31:6+I_INDEX_BITS]; i_valid<=1;
                                if(I_WAYS>1 && !instruction_valid_second[i_index])begin
                                    instruction_tags_second[i_index]<=~i_address[31:6+I_INDEX_BITS];
                                    i_second_tag<=~i_address[31:6+I_INDEX_BITS];
                                end
                            end
                            i_state<=I_LOOKUP;
                        end
                    end else i_beat<=i_beat+3'd1;
                end
                I_ERROR: if (i_complete) i_state<=I_IDLE;
                default: begin end
            endcase
            // Acceptance has priority over completing the previous response.
            // A hit can therefore accept the next request on the same edge.
            if (new_i) begin
                i_address<=imem_request_address;
                i_crossing<=0; i_first_error<=0;
                if (!executable(imem_request_address) || imem_request_address[1:0]!=0) begin
                    i_state<=I_ERROR; i_error_bits<=2'b11; begin i_error_data_snapshot<=0;i_error_word_valid<=0;end
                end else begin
                    i_state<=I_LOOKUP;
                end
            end

            if(i_speculative_read)begin
                // Snapshot both tags at exactly the payload-read edge. No
                // maintenance can complete while an instruction is owned.
                // A refill of word0 cannot modify the distinct word1 index.
                if(ENABLE_FAST_ICROSS)begin
                    i_next_tag<=instruction_tags[new_i_next_index];
                    i_next_valid<=instruction_valid[new_i_next_index];
                    i_next_second_tag<=instruction_tags_second[new_i_next_index];
                    i_next_second_valid<=I_WAYS>1 && instruction_valid_second[new_i_next_index];
                end
                i_even_ram_select<=1'b1;i_odd_ram_select<=1'b1;
                i_tag<=instruction_tags[imem_request_address[6+I_INDEX_BITS-1:6]];
                i_valid<=instruction_valid[imem_request_address[6+I_INDEX_BITS-1:6]];
                i_second_tag<=instruction_tags_second[imem_request_address[6+I_INDEX_BITS-1:6]];
                i_second_valid<=I_WAYS>1 && instruction_valid_second[imem_request_address[6+I_INDEX_BITS-1:6]];
                i_lru<=instruction_lru[imem_request_address[6+I_INDEX_BITS-1:6]];
                if(i_complete && i_state==I_LOOKUP)begin
                    if(imem_request_address[6+I_INDEX_BITS-1:6]==i_index)i_lru<=!i_hit_way;
                    if(i_fast_cross_hit && imem_request_address[6+I_INDEX_BITS-1:6]==i_next_index)i_lru<=!i_next_hit_way;
                end
            end
            // Touch only owned, consumed lines, including both halves of a
            // fast cross-line response. Held responses retain their payload.
            if(i_state==I_LOOKUP && i_hit && (i_complete || i_ram_cross_lookup))
                instruction_lru[i_index]<=!i_hit_way;
            if(i_state==I_LOOKUP && i_hit && i_complete && i_fast_cross_hit)
                instruction_lru[i_next_index]<=!i_next_hit_way;
            case (d_state)
                D_IDLE: if (fence_pending && i_state==I_IDLE) begin
                    sweep_index<=0; sweep_way<=0; d_state<=D_SWEEP_READ;
                end
                D_LOOKUP: begin
                    if (d_hit) begin
                        if (d_complete) begin
                            if (d_write) begin
                                if(selected_way)begin
                                    // Store byte enables use the common RAM write port.
                                    data_dirty_second[d_index]<=1'b1;
                                end else begin
                                    // Store byte enables use the common RAM write port.
                                    data_dirty[d_index]<=1'b1;
                                end
                            end
                            data_lru[d_index]<=!selected_way;
                            d_state<=D_IDLE;
                        end
                    end else if (selected_valid && selected_dirty) begin
                        request_way<=selected_way;
                        writeback_way<=selected_way;
                        writeback_address<={selected_tag,d_index,6'b0};
                        writeback_index<=d_index;
                        writeback_is_sweep<=0;
                        d_beat<=0; d_state<=D_WRITE_READ;
                    end else begin
                        request_way<=selected_way;
                        d_beat<=0; d_fill_error<=0; d_state<=D_READ_COMMAND;
                    end
                end
                D_READ_COMMAND: if (data_rd_gnt_i) begin
                    d_state<=D_FILL; d_beat<=0; d_fill_error<=0;
                    if(request_way)data_valid_second[d_index]<=0;
                    else data_valid[d_index]<=0;
                    if (data_rd_rvalid_i) begin
                        if(request_way)begin
                            // Refill uses the common RAM write port.
                            if(d_address[5:3]==0)begin d_second_bypass<=data_rd_rdata_i; d_second_ram_select<=1'b0; end
                        end else begin
                            // Refill uses the common RAM write port.
                            if(d_address[5:3]==0)begin d_first_bypass<=data_rd_rdata_i; d_first_ram_select<=1'b0; end
                        end
                        d_beat<=1;
                        d_fill_error<=data_rd_err_i || data_rd_rid_i!=1'b0;
                    end
                end
                D_FILL: if (data_rd_rvalid_i) begin
                    if(request_way)begin
                        // Refill uses the common RAM write port.
                        if(d_beat==d_address[5:3])begin d_second_bypass<=data_rd_rdata_i; d_second_ram_select<=1'b0; end
                    end else begin
                        // Refill uses the common RAM write port.
                        if(d_beat==d_address[5:3])begin d_first_bypass<=data_rd_rdata_i; d_first_ram_select<=1'b0; end
                    end
                    d_fill_error<=d_fill_error || data_rd_err_i || data_rd_rid_i!=1'b0;
                    if (d_beat==3'd7) begin
                        if (d_fill_error || data_rd_err_i || data_rd_rid_i!=1'b0) begin
                            d_result<=0; d_result_error<=1; d_state<=D_RESPONSE;
                        end else begin
                            if(request_way)begin
                                data_tags_second[d_index]<=d_address[31:6+D_INDEX_BITS];
                                data_valid_second[d_index]<=1; data_dirty_second[d_index]<=0;
                                d_second_tag<=d_address[31:6+D_INDEX_BITS]; d_second_valid<=1; d_second_dirty<=0;
                            end else begin
                                data_tags[d_index]<=d_address[31:6+D_INDEX_BITS];
                                data_valid[d_index]<=1; data_dirty[d_index]<=0;
                                d_tag<=d_address[31:6+D_INDEX_BITS]; d_valid<=1; d_dirty<=0;
                            end
                            d_state<=D_LOOKUP;
                        end
                    end else d_beat<=d_beat+3'd1;
                end
                D_WRITE_READ: begin
                    if(writeback_way)d_second_ram_select<=1'b1;
                    else d_first_ram_select<=1'b1;
                    d_state<=D_WRITE_BEATS;
                end
                D_WRITE_BEATS: if (data_wr_gnt_i) begin
                    if (d_beat==3'd7) begin
                        d_state<=D_WRITE_ACK;
                        // Accept a zero-latency completion on the final beat.
                        if (data_wr_bvalid_i && data_wr_bid_i==1'b0) begin
                            if (data_wr_berr_i) begin d_beat<=0; d_state<=D_WRITE_READ; end
                            else begin
                                if(writeback_way)data_dirty_second[writeback_index]<=0;
                                else data_dirty[writeback_index]<=0;
                                if (writeback_is_sweep) begin
                                    if (invalidate_data)begin
                                        if(writeback_way)data_valid_second[writeback_index]<=0;
                                        else data_valid[writeback_index]<=0;
                                    end
                                    if (sweep_is_last) begin
                                        for(n=0;n<I_LINES;n=n+1)begin instruction_valid[n]<=0;instruction_valid_second[n]<=0;end
                                        fence_pending<=fence_i || fence_d;
                                        invalidate_data<=fence_d;
                                        d_state<=D_IDLE;
                                    end else begin
                                        if(D_WAYS>1 && !sweep_way)sweep_way<=1;
                                        else begin sweep_way<=0; sweep_index<=sweep_index+1'b1; end
                                        d_state<=D_SWEEP_READ;
                                    end
                                end else begin d_beat<=0; d_state<=D_READ_COMMAND; end
                            end
                        end
                    end else begin
                        d_beat<=next_write_beat;
                        if(writeback_way)d_second_ram_select<=1'b1;
                        else d_first_ram_select<=1'b1;
                    end
                end
                D_WRITE_ACK: if (data_wr_bvalid_i && data_wr_bid_i==1'b0) begin
                    if (data_wr_berr_i) begin d_beat<=0; d_state<=D_WRITE_READ; end
                    else begin
                        if(writeback_way)data_dirty_second[writeback_index]<=0;
                        else data_dirty[writeback_index]<=0;
                        if (writeback_is_sweep) begin
                            if (invalidate_data)begin
                                if(writeback_way)data_valid_second[writeback_index]<=0;
                                else data_valid[writeback_index]<=0;
                            end
                            if (sweep_is_last) begin
                                for(n=0;n<I_LINES;n=n+1)begin instruction_valid[n]<=0;instruction_valid_second[n]<=0;end
                                fence_pending<=fence_i || fence_d;
                                invalidate_data<=fence_d;
                                d_state<=D_IDLE;
                            end else begin
                                if(D_WAYS>1 && !sweep_way)sweep_way<=1;
                                else begin sweep_way<=0; sweep_index<=sweep_index+1'b1; end
                                d_state<=D_SWEEP_READ;
                            end
                        end else begin d_beat<=0; d_state<=D_READ_COMMAND; end
                    end
                end
                D_IO_COMMAND: if (periph_gnt_i) begin
                    d_state<=D_IO_WAIT;
                    if (periph_rvalid_i) begin
                        d_result<=periph_rdata_i; d_result_error<=periph_err_i; d_state<=D_RESPONSE;
                    end
                end
                D_IO_WAIT: if (periph_rvalid_i) begin
                    d_result<=periph_rdata_i; d_result_error<=periph_err_i; d_state<=D_RESPONSE;
                end
                D_RESPONSE: if (d_complete) d_state<=D_IDLE;
                D_SWEEP_READ: begin
                    if(sweep_way)begin
                        d_tag<=data_tags_second[sweep_index];
                        d_valid<=data_valid_second[sweep_index]; d_dirty<=data_dirty_second[sweep_index];
                    end else begin
                        d_tag<=data_tags[sweep_index];
                        d_valid<=data_valid[sweep_index]; d_dirty<=data_dirty[sweep_index];
                    end
                    d_state<=D_SWEEP_CHECK;
                end
                D_SWEEP_CHECK: begin
                    if (d_valid && d_dirty) begin
                        writeback_address<={d_tag,sweep_index,6'b0};
                        writeback_way<=sweep_way;
                        writeback_index<=sweep_index; writeback_is_sweep<=1;
                        d_beat<=0; d_state<=D_WRITE_READ;
                    end else begin
                        if (invalidate_data)begin
                            if(sweep_way)data_valid_second[sweep_index]<=0;
                            else data_valid[sweep_index]<=0;
                        end
                        if (sweep_is_last) begin
                            for(n=0;n<I_LINES;n=n+1)begin instruction_valid[n]<=0;instruction_valid_second[n]<=0;end
                            fence_pending<=fence_i || fence_d;
                            invalidate_data<=fence_d;
                            d_state<=D_IDLE;
                        end else begin
                            if(D_WAYS>1 && !sweep_way)sweep_way<=1;
                            else begin sweep_way<=0; sweep_index<=sweep_index+1'b1; end
                            d_state<=D_SWEEP_READ;
                        end
                    end
                end
                default: begin end
            endcase
            // A held response has ready=0, so speculative data/tag reads
            // cannot replace its payload. Keep the original same-edge store
            // write forwarding and LRU/dirty bypass over these private reads.
            if(d_speculative_read)begin
                    d_first_ram_select<=1'b1; d_tag<=data_tags[next_d_index];
                    d_valid<=data_valid[next_d_index]; d_dirty<=data_dirty[next_d_index];
                    d_lru<=data_lru[next_d_index];
                    if(D_WAYS>1)begin
                        d_second_ram_select<=1'b1;
                        d_second_tag<=data_tags_second[next_d_index];
                        d_second_valid<=data_valid_second[next_d_index];
                        d_second_dirty<=data_dirty_second[next_d_index];
                    end else begin d_second_valid<=0; d_second_dirty<=0; end
                    if(d_complete && d_state==D_LOOKUP && next_d_index==d_index)
                        d_lru<=!selected_way;
                    // Explicit write-to-read forwarding avoids dependence on
                    // vendor-specific read-during-write memory behavior.
                    if (d_complete && d_state==D_LOOKUP && d_write && next_d_index==d_index) begin
                        if(selected_way)begin
                            d_second_dirty<=1;
                            if(next_d_segment==d_segment_index)begin d_second_bypass<=updated_data_segment; d_second_ram_select<=1'b0; end
                        end else begin
                            d_dirty<=1;
                            if(next_d_segment==d_segment_index)begin d_first_bypass<=updated_data_segment; d_first_ram_select<=1'b0; end
                        end
                    end
            end
            if(d_payload_free)begin
                d_address<=dmem_request_address; d_write<=dmem_request_write;
                d_wdata<=dmem_request_wdata; d_wstrb<=dmem_request_wstrb; d_size<=dmem_request_size;
            end
            if (new_d) begin
                // Preserve MMIO precedence and all original IO handshakes.
                // Only an accepted request owns this registered fault; held
                // responses, killed-load identity and alignment remain under
                // the unchanged cache/core transaction and exception rules.
                if (peripheral(dmem_request_address)) d_state<=D_IO_COMMAND;
                else if (!data_ram_mapped(dmem_request_address)) begin
                    d_result<=0; d_result_error<=1; d_state<=D_RESPONSE;
                end else begin
                    d_state<=D_LOOKUP;

                end
            end
        end
    end
endmodule
